    /// A consumer that requests Checkpoint on every event.
    struct CheckpointEveryEvent {
        pub recorded: usize,
    }

    impl<W: SemiringRef> WalkerConsumer<W> for CheckpointEveryEvent {
        fn on_event(&mut self, _event: &WpdaEvent<W>, _state: &WpdaState) -> WpdaControl {
            WpdaControl::Checkpoint
        }
        fn on_checkpoint(&mut self, _config: &WpdaConfiguration<W>) {
            self.recorded += 1;
        }
    }

    #[test]
    fn checkpoint_consumer_records_per_step() {
        let engine = ScriptedEngine::new(vec![
            WpdaStepAction::Accept,
            WpdaStepAction::Advance(WpdaState::InfixLoop { cur_bp: 0 }),
            WpdaStepAction::Advance(WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 }),
        ]);
        let mut walker: WpdaWalker<LexicographicWeight, _> = WpdaWalker::new(engine, 0);
        let mut consumer = CheckpointEveryEvent { recorded: 0 };
        let _ = walker.run_with_consumer(&mut consumer, 100, &empty_tokens());
        // At least one checkpoint should be recorded per non-terminal step.
        assert!(consumer.recorded >= 2, "expected ≥2 checkpoints, got {}", consumer.recorded);
    }

    /// A consumer that pauses on the first event.
    struct PauseOnFirst {
        pub paused: bool,
    }

    impl<W: SemiringRef> WalkerConsumer<W> for PauseOnFirst {
        fn on_event(&mut self, _event: &WpdaEvent<W>, _state: &WpdaState) -> WpdaControl {
            if !self.paused {
                self.paused = true;
                WpdaControl::Pause
            } else {
                WpdaControl::Continue
            }
        }
    }

    #[test]
    fn pause_consumer_stops_walker_without_completion() {
        let engine = ScriptedEngine::new(vec![
            WpdaStepAction::Accept,
            WpdaStepAction::Advance(WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 }),
        ]);
        let mut walker: WpdaWalker<LexicographicWeight, _> = WpdaWalker::new(engine, 0);
        let mut consumer = PauseOnFirst { paused: false };
        let s = walker.run_with_consumer(&mut consumer, 100, &empty_tokens());
        // Pause should leave walker in non-terminal state, ready for resumption.
        assert!(!s.is_terminal(), "pause should not enter a terminal state");
        assert!(consumer.paused);
    }

    // ─── Phase A.2: atomic-rule plumbing integration tests ──────────────────

    /// Test engine that simulates an atomic integer-literal rule.
    ///
    /// State transitions:
    /// - `Ready` → emits `Push(CategoryEntry)` + → `PrefixDispatch`
    /// - `PrefixDispatch` + sees Integer token → `ConsumeAndPush(Return)` + → `Unwinding`
    /// - `Unwinding` + frontier is `Return` → `Pop` + → `Unwinding`
    /// - `Unwinding` + frontier is `CategoryEntry` → `Pop` + → `InfixLoop`
    /// - `InfixLoop` + no operator candidate → `Advance(Unwinding)`
    /// - `Unwinding` + no frontier → `Accept`
    struct AtomicIntEngine;

    impl WpdaEngine<LexicographicWeight> for AtomicIntEngine {
        fn step(
            &self,
            state: &WpdaState,
            _gss: &WpdaGss<LexicographicWeight>,
            frontier_top: Option<&WpdaGssNode>,
            _pos: usize,
            tokens: &dyn WpdaTokenSource,
            _frame_ctx: crate::wpda_runtime::FrameCtx,
        ) -> WpdaStepAction<LexicographicWeight> {
            match state {
                WpdaState::Ready { min_bp } => WpdaStepAction::Push {
                    symbol: StackSymbolV2::category_entry(0),
                    weight: LexicographicWeight::from_cost(0.0, 0, 0),
                    new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: *min_bp },
                },
                WpdaState::PrefixDispatch { pos, cur_bp } => {
                    if let Some(TokenKind::Integer) = tokens.peek_kind(*pos) {
                        WpdaStepAction::ConsumeAndPush {
                            symbol: StackSymbolV2::rule_at(0, 0, 0, None).with_kind_return(),
                            weight: LexicographicWeight::from_cost(0.0, 0, 0),
                            new_state: WpdaState::Unwinding,
                            trigger_mode: TriggerMode::CaptureForBuilder,
                        }
                    } else {
                        let _ = cur_bp;
                        WpdaStepAction::Error("expected Integer".into())
                    }
                },
                WpdaState::Unwinding => match frontier_top.map(|n| n.symbol.kind) {
                    Some(SymbolKind::Return) => WpdaStepAction::Pop {
                        weight: LexicographicWeight::one(),
                        new_state: WpdaState::Unwinding,
                    },
                    Some(SymbolKind::CategoryEntry) => WpdaStepAction::Pop {
                        weight: LexicographicWeight::one(),
                        new_state: WpdaState::InfixLoop { cur_bp: 0 },
                    },
                    _ => WpdaStepAction::Accept,
                },
                WpdaState::InfixLoop { .. } => WpdaStepAction::Advance(WpdaState::Unwinding),
                _ => WpdaStepAction::Idle,
            }
        }

        fn action_for(&self, src_idx: u16, rule_idx: u16) -> Option<&ActionEntry> {
            fn int_lit_action(b: &mut SemanticBuilder, args: Vec<ActionArg>) {
                // Pop the captured token, parse its text, push the parsed i64.
                let arg = args.into_iter().next().expect("arity 1");
                let text = arg.as_token_text().unwrap_or("0");
                let parsed: i64 = text.parse().unwrap_or(0);
                b.push_term::<i64>(parsed);
            }
            static ACTION: ActionEntry = ActionEntry {
                action_fn: int_lit_action,
                arity: 1,
                expected_input_cats: &[crate::wpda_runtime::ANY_CAT],
                output_cat: 0,
            };
            if src_idx == 0 && rule_idx == 0 {
                Some(&ACTION)
            } else {
                None
            }
        }
    }

    #[derive(Clone, Copy)]
    struct ChainSynthIntEngine {
        integer_has_non_atom_start: bool,
    }

    impl ChainSynthIntEngine {
        const PLAIN: Self = Self { integer_has_non_atom_start: false };
        const INTEGER_AMBIGUOUS: Self = Self { integer_has_non_atom_start: true };
    }

    impl WpdaEngine<LexicographicWeight> for ChainSynthIntEngine {
        fn step(
            &self,
            _state: &WpdaState,
            _gss: &WpdaGss<LexicographicWeight>,
            _frontier_top: Option<&WpdaGssNode>,
            _pos: usize,
            _tokens: &dyn WpdaTokenSource,
            _frame_ctx: crate::wpda_runtime::FrameCtx,
        ) -> WpdaStepAction<LexicographicWeight> {
            WpdaStepAction::Idle
        }

        fn action_for(&self, src_idx: u16, rule_idx: u16) -> Option<&ActionEntry> {
            fn int_lit_action(b: &mut SemanticBuilder, args: Vec<ActionArg>) {
                let arg = args.into_iter().next().expect("arity 1");
                let text = arg.as_token_text().unwrap_or("0");
                let parsed: i64 = text.parse().unwrap_or(0);
                b.push_term::<i64>(parsed);
            }
            static ACTION: ActionEntry = ActionEntry {
                action_fn: int_lit_action,
                arity: 1,
                expected_input_cats: &[crate::wpda_runtime::ANY_CAT],
                output_cat: 0,
            };
            if src_idx == 0 && rule_idx == 0 {
                Some(&ACTION)
            } else {
                None
            }
        }

        fn chain_atom_producers_for_token(
            &self,
            cat_src_idx: u16,
            kind: &TokenKind,
            _text: Option<&str>,
        ) -> Vec<ChainAtomProducer> {
            if cat_src_idx == 0 && matches!(kind, TokenKind::Integer) {
                vec![ChainAtomProducer::direct(0, 0)]
            } else {
                Vec::new()
            }
        }

        fn prefix_token_has_non_atom_start(
            &self,
            cat_src_idx: u16,
            kind: &TokenKind,
            _text: Option<&str>,
        ) -> bool {
            cat_src_idx == 0
                && ((self.integer_has_non_atom_start && matches!(kind, TokenKind::Integer))
                    || matches!(kind, TokenKind::Fixed(text) if text == "wrap"))
        }

        fn category_recognizes_operator(&self, cat: u16, token_text: &str) -> bool {
            cat == 0 && matches!(token_text, "+" | "*")
        }
    }

    use crate::wpda_runtime::{ActionArg, ActionEntry, SemanticBuilder, SliceTokenSource};

    fn lex_alt(
        kind: TokenKind,
        text: &str,
        end_byte: usize,
        weight: f64,
    ) -> crate::lexer_types::LexAlternative {
        crate::lexer_types::LexAlternative {
            kind,
            text: text.to_string(),
            end_byte,
            weight: crate::automata::semiring::TropicalWeight(weight),
        }
    }

    #[test]
    fn right_assoc_chain_synthesis_ignores_irrelevant_same_span_lex_alts() {
        let stream = crate::lexer_types::LexStream {
            entries: vec![
                crate::lexer_types::LexEntry {
                    byte_start: 0,
                    alternatives: vec![
                        lex_alt(TokenKind::Integer, "2", 1, 0.0),
                        lex_alt(TokenKind::Ident, "2", 1, 1.0),
                    ],
                },
                crate::lexer_types::LexEntry {
                    byte_start: 2,
                    alternatives: vec![lex_alt(TokenKind::Fixed("^".into()), "^", 3, 0.0)],
                },
                crate::lexer_types::LexEntry {
                    byte_start: 4,
                    alternatives: vec![
                        lex_alt(TokenKind::Integer, "2", 5, 0.0),
                        lex_alt(TokenKind::Ident, "2", 5, 1.0),
                    ],
                },
                crate::lexer_types::LexEntry {
                    byte_start: 6,
                    alternatives: vec![lex_alt(TokenKind::Fixed("^".into()), "^", 7, 0.0)],
                },
                crate::lexer_types::LexEntry {
                    byte_start: 8,
                    alternatives: vec![
                        lex_alt(TokenKind::Integer, "2", 9, 0.0),
                        lex_alt(TokenKind::Ident, "2", 9, 1.0),
                    ],
                },
            ],
        };
        let token_src = crate::wpda_runtime::MultiTokenSource::new(stream);
        assert!(peek_binary_chain(&token_src, 1, 3));

        let mut walker = WpdaWalker::new(ChainSynthIntEngine::PLAIN, 0);
        let mut cursor = BranchCursor::seed_from_live(
            crate::gss::GSS_NODE_NONE,
            1,
            LexicographicWeight::one(),
            WpdaState::InfixLoop { cur_bp: 0 },
        );
        let head = walker
            .intern_chain_atom_symbol(0, 1, &TokenKind::Integer, "2", 0, 0)
            .expect("head atom should intern");
        cursor.sppf_stack_id = walker
            .sppf_stack_arena
            .intern_push(cursor.sppf_stack_id, head);
        let spec = crate::binding_power::IterAbsorbSpec {
            left_bp: 27,
            right_bp: 26,
            assoc_right: true,
            is_mixfix: false,
            op_cat_src_idx: 0,
            op_rule_idx: 1,
            atom_cat_src_idx: 0,
            atom_lit_rule_idx: 0,
            trigger: "",
            sep: "",
        };

        let (root, _weight, chain_end) = walker
            .synth_binary_chain(&cursor, &token_src, &spec, LexicographicWeight::one())
            .expect("typed Int chain synthesis should ignore non-Int lex alternatives");
        assert_eq!(chain_end, 5);
        match walker.sppf.node(root).expect("root must exist") {
            crate::sppf::SppfNode::Symbol { non_terminal_tag, lo_pos, hi_pos, .. } => {
                assert_eq!((*non_terminal_tag, *lo_pos, *hi_pos), (0, 0, 5));
            },
            other => panic!("expected synthesized root Symbol, got {other:?}"),
        }
    }

