    /// Stage 3.9 / ι Phase 4 regression-fix test (2026-05-01): a Push of
    /// `OptionalGroupAt(1)` MUST open the optional scope in deterministic mode.
    /// Pre-fix: `apply_action_to_cursor::Push` lost the
    /// `OptionalGroupAt(1) → start_optional_scope()` clause during the
    /// Step-4.4 helper rewrite. Post-fix: `emit_push_side_effects`
    /// centralizes both `CollectionMarker` (id allocation) and
    /// `OptionalGroupAt(1)` (scope opening) implicit Push-time effects.
    #[test]
    fn push_optional_group_at_one_opens_scope_in_deterministic_mode() {
        let engine = ScriptedEngine::new(vec![WpdaStepAction::Push {
            symbol: StackSymbolV2::optional_group_at(0, 0, 1, 0),
            weight: lex(0.0, 0, 0),
            new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
        }]);
        let mut w = WpdaWalker::new(engine, 0);
        assert!(w.deterministic());
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens());
        // Still deterministic (no Fork). The cursor must have an open
        // optional scope so subsequent inner pushes land in the inner Vec.
        assert!(w.deterministic());
        // Phase F.3c.1 (2026-05-20): inspect the SPPF-side mirror
        // `cursor.optional_scope_marks` instead of `walker.builder()`
        // (deleted in F.3c.5).
        let cursors = w.branch_cursors_for_test();
        assert_eq!(cursors.len(), 1);
        assert_eq!(
            cursors[0].optional_scope_marks.len(),
            1,
            "Push of OptionalGroupAt(1) must open optional scope in deterministic mode",
        );
    }

    /// Stage 3.9 / ι Phase 4 regression-fix test (2026-05-01); reshaped
    /// in Phase 5.6-tail-B (2026-05-12): pre-tail this checked the
    /// cursor's `recovery_deltas` for a `BuilderDelta::StartOptionalScope`
    /// entry. Under always-eager Arc::make_mut (Phase 5.3+) and emit-helper
    /// unification (5.6-tail-B), emit_start_optional_scope no longer
    /// journals — it mutates `cursor.builder.optional_stack` directly via
    /// Arc::make_mut. The reshaped assertion observes the optional scope
    /// directly on cursor.builder.
    #[test]
    fn push_optional_group_at_one_opens_scope_in_nondeterministic_mode() {
        let engine = ScriptedEngine::new(vec![
            WpdaStepAction::Push {
                symbol: StackSymbolV2::optional_group_at(0, 0, 1, 0),
                weight: lex(0.0, 0, 0),
                new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
            },
            // Force nondeterministic mode via a single-branch Fork BEFORE the OptionalGroupAt push.
            WpdaStepAction::Fork {
                branches: vec![ForkBranch {
                    symbol: StackSymbolV2::category_entry(0),
                    weight: lex(0.0, 0, 0),
                    new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
                    action_kind: ForkActionKind::Push,
                }],
                consume_trigger: false,
            },
        ]);
        let mut w = WpdaWalker::new(engine, 0);
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens()); // Fork → nondeterministic
        assert!(!w.deterministic());
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens()); // Push (under fanout)
                                                                   // The cursor must show an open optional scope.
        let cursors = w.branch_cursors_for_test();
        assert_eq!(cursors.len(), 1);
        // Phase F.3c.1 (2026-05-20): inspect the SPPF-side mirror
        // `cursor.optional_scope_marks` instead of `cursor.builder`
        // (deleted in F.3c.4).
        assert_eq!(
            cursors[0].optional_scope_marks.len(),
            1,
            "Push of OptionalGroupAt(1) in nondeterministic mode must open an optional scope \
             on the cursor's optional_scope_marks (mirrored by emit_start_optional_scope)",
        );
    }

    /// Stage 3.9 / ι Phase 4 regression-fix test (2026-05-01): regression
    /// guard. Push of `OptionalGroupAt(2)` (or any sub_pos != 1) must NOT
    /// open the optional scope — only the FIRST marker (sub_pos=1) opens.
    /// Subsequent OptionalGroupAt(2..N) advance through the group's inner
    /// items and must NOT re-open the scope.
    #[test]
    fn push_optional_group_at_two_does_not_open_scope() {
        let engine = ScriptedEngine::new(vec![WpdaStepAction::Push {
            symbol: StackSymbolV2::optional_group_at(0, 0, 2, 0),
            weight: lex(0.0, 0, 0),
            new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
        }]);
        let mut w = WpdaWalker::new(engine, 0);
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens());
        // Phase F.3c.1 (2026-05-20): inspect SPPF-side mirror instead of
        // walker.builder() (deleted in F.3c.5).
        let cursors = w.branch_cursors_for_test();
        assert_eq!(cursors.len(), 1);
        assert_eq!(
            cursors[0].optional_scope_marks.len(),
            0,
            "OptionalGroupAt(2) must NOT open a new scope (only sub_pos=1 does)",
        );
    }

    /// Helper inlining: a single Push in deterministic mode mutates the live GSS
    /// without populating cursor.recovery_deltas.
    #[test]
    fn phase4_helper_inlining_does_not_double_emit() {
        // Push a distinct symbol (rule_at) so GSS dedup doesn't collapse
        // the sentinel CategoryEntry(0) root with the pushed symbol.
        let engine = ScriptedEngine::new(vec![WpdaStepAction::Push {
            symbol: StackSymbolV2::rule_at(0, 1, 0, Some(7)),
            weight: lex(0.0, 0, 0),
            new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
        }]);
        let mut w = WpdaWalker::new(engine, 0);
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens());
        // Push grows GSS by ≥2 nodes (CategoryEntry root + pushed entry).
        assert!(w.gss().node_count() >= 2);
        // Unforked: no recovery deltas accumulated (non-recovery
        // mutations land on cursor.builder directly).
        let cursors = w.branch_cursors_for_test();
        assert_eq!(cursors.len(), 1);
        assert!(
            cursors[0].recovery_deltas.is_empty(),
            "deterministic: live mutation on cursor.builder, no recovery delta"
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    // Stage 3.16 / Cluster 1+2+3 Mechanism γ — Fork-emission invariants
    // (Commit 2 closure, 2026-05-06).
    //
    // These tests exercise the new payload-carrying ForkActionKind variants
    // (ConsumeAndReplace, Consume, ConsumeIdentAndReplace, Pop, ConsumeAndPop,
    // ConsumeAndReplaceWithEffect, LexAlt, ConsumeAndCaptureAndPush) via the
    // ScriptedEngine harness. Verify that each variant's apply_action::Fork
    // dispatch arm produces the expected cursor state mutations.
    //
    // Synthetic-grammar coverage matches the G1-G5 future-grammar shapes
    // designed in /home/dylon/.claude/plans/commit2-h7-h8-tests-resolution-2026-05-05.md
    // — at the walker level (not full grammar codegen) since shipped
    // grammars exercise Mechanism γ end-to-end via gen_calculator_op (1331+),
    // gen_rhocalc_op (532), gen_optsmoke_op (25), gen_mixedmath_op (199).
    // ════════════════════════════════════════════════════════════════════════

    /// Mechanism γ — `Advance` fork branch changes state without consuming
    /// input or mutating the GSS. This models evidence-preserving
    /// fall-through branches alongside consuming lex alternatives.
    #[test]
    fn fork_action_advance_preserves_pos_and_gss() {
        let engine = ScriptedEngine::new(vec![
            WpdaStepAction::Accept,
            WpdaStepAction::Fork {
                branches: vec![ForkBranch {
                    symbol: StackSymbolV2::category_entry(0),
                    weight: lex(0.0, 0, 0),
                    new_state: WpdaState::Unwinding,
                    action_kind: ForkActionKind::Advance,
                }],
                consume_trigger: false,
            },
            WpdaStepAction::Push {
                symbol: StackSymbolV2::category_entry(0),
                weight: lex(0.0, 0, 0),
                new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
            },
        ]);
        let mut w = WpdaWalker::new(engine, 0);
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens());
        let pos_before = w.position();
        let gss_count_before = w.gss().node_count();
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens());
        let cursors = w.branch_cursors_for_test();
        assert_eq!(cursors.len(), 1);
        assert_eq!(cursors[0].pos, pos_before, "Advance must not consume input");
        assert_eq!(
            w.gss().node_count(),
            gss_count_before,
            "Advance must not push or pop GSS nodes",
        );
        assert!(matches!(cursors[0].inner_state, WpdaState::Unwinding));
    }

    struct TargetOwnedOperatorProbeEngine;

    impl WpdaEngine<LexicographicWeight> for TargetOwnedOperatorProbeEngine {
        fn step(
            &self,
            state: &WpdaState,
            _gss: &WpdaGss<LexicographicWeight>,
            frontier_top: Option<&WpdaGssNode>,
            pos: usize,
            tokens: &dyn WpdaTokenSource,
            _frame_ctx: crate::wpda_runtime::FrameCtx,
        ) -> WpdaStepAction<LexicographicWeight> {
            let target_cat = frontier_top.map(|node| node.symbol.category_src_idx);
            let token_text = tokens.peek_text(pos).unwrap_or("");
            if target_cat == Some(1)
                && token_text == "+"
                && matches!(state, WpdaState::InfixLoop { cur_bp } if *cur_bp <= 2)
            {
                return WpdaStepAction::ConsumeAndPush {
                    symbol: StackSymbolV2::rule_at(1, 0, 0, Some(0)).with_kind_return(),
                    weight: lex(0.0, 1, 0),
                    new_state: WpdaState::PrefixDispatch { pos: pos + 1, cur_bp: 3 },
                    trigger_mode: TriggerMode::Discard,
                };
            }
            WpdaStepAction::Advance(WpdaState::Unwinding)
        }

        fn category_recognizes_operator(&self, cat: u16, token_text: &str) -> bool {
            cat == 1 && token_text == "+"
        }

        fn category_accepts_operator_at_floor(
            &self,
            cat: u16,
            token_text: &str,
            floor: u8,
        ) -> bool {
            cat == 1 && token_text == "+" && floor <= 2
        }
    }

    #[test]
    fn transparent_reentry_treats_target_floor_blocked_operator_as_boundary() {
        let token_kinds = [TokenKind::Fixed("+".into()), TokenKind::Eof];
        let token_texts = ["+", ""];
        let token_src = SliceTokenSource::with_texts(&token_kinds, &token_texts);
        let w = WpdaWalker::new(TargetOwnedOperatorProbeEngine, 0);
        let cursor = w.branch_cursors_for_test()[0].clone();

        assert!(
            w.target_category_rejects_own_operator_at_floor(1, "+", &cursor, 3, &token_src),
            "a target-owned operator rejected by the target floor is a boundary"
        );
        assert!(
            !w.target_category_rejects_own_operator_at_floor(1, "+", &cursor, 0, &token_src),
            "an operator accepted at the active target floor is not a reentry boundary"
        );
        assert!(
            !w.target_category_rejects_own_operator_at_floor(2, "+", &cursor, 3, &token_src),
            "source-only operators remain eligible for transparent source reentry"
        );
    }

    struct ProjectionBoundaryProbeEngine;

    impl WpdaEngine<LexicographicWeight> for ProjectionBoundaryProbeEngine {
        fn step(
            &self,
            state: &WpdaState,
            _gss: &WpdaGss<LexicographicWeight>,
            frontier_top: Option<&WpdaGssNode>,
            pos: usize,
            tokens: &dyn WpdaTokenSource,
            _frame_ctx: crate::wpda_runtime::FrameCtx,
        ) -> WpdaStepAction<LexicographicWeight> {
            let cat = frontier_top.map(|node| node.symbol.category_src_idx);
            let token_text = tokens.peek_text(pos).unwrap_or("");
            match (cat, token_text, state) {
                (Some(1), "+", WpdaState::InfixLoop { cur_bp }) if *cur_bp <= 2 => {
                    WpdaStepAction::ConsumeAndPush {
                        symbol: StackSymbolV2::rule_at(1, 0, 0, Some(*cur_bp)).with_kind_return(),
                        weight: lex(0.0, 1, 0),
                        new_state: WpdaState::PrefixDispatch { pos: pos + 1, cur_bp: 3 },
                        trigger_mode: TriggerMode::Discard,
                    }
                },
                (Some(2), "+", WpdaState::InfixLoop { cur_bp }) if *cur_bp <= 4 => {
                    WpdaStepAction::ConsumeAndPush {
                        symbol: StackSymbolV2::rule_at(2, 0, 0, Some(*cur_bp)).with_kind_return(),
                        weight: lex(0.0, 2, 0),
                        new_state: WpdaState::PrefixDispatch { pos: pos + 1, cur_bp: 5 },
                        trigger_mode: TriggerMode::Discard,
                    }
                },
                _ => WpdaStepAction::Advance(WpdaState::Unwinding),
            }
        }

        fn category_recognizes_operator(&self, cat: u16, token_text: &str) -> bool {
            matches!((cat, token_text), (1, "+") | (2, "+"))
        }

        fn category_accepts_operator_at_floor(
            &self,
            cat: u16,
            token_text: &str,
            floor: u8,
        ) -> bool {
            matches!((cat, token_text), (1, "+") if floor <= 2)
                || matches!((cat, token_text), (2, "+") if floor <= 4)
        }
    }

    #[test]
    fn projection_target_floor_block_suppresses_source_operator_branch() {
        let token_kinds = [TokenKind::Fixed("+".into()), TokenKind::Eof];
        let token_texts = ["+", ""];
        let token_src = SliceTokenSource::with_texts(&token_kinds, &token_texts);
        let mut w = WpdaWalker::new(ProjectionBoundaryProbeEngine, 0);
        let mut cursor = w.branch_cursors_for_test()[0].clone();
        cursor.inner_state = WpdaState::InfixLoop { cur_bp: 3 };
        let _ = w.cursor_gss_push_with_kind(
            &mut cursor,
            StackSymbolV2::category_entry(2),
            0,
            lex(0.0, 2, 0),
            crate::gss::EdgeKind::CrossCatProjection {
                source_src_idx: 2,
                inner_cur_bp: 3,
                wrap_cat: 1,
                wrap_rule: 0,
            },
        );

        let guarded = w.guard_crosscat_projection_target_boundary(
            &cursor,
            WpdaStepAction::ConsumeAndPush {
                symbol: StackSymbolV2::rule_at(2, 0, 0, Some(3)).with_kind_return(),
                weight: lex(0.0, 2, 0),
                new_state: WpdaState::PrefixDispatch { pos: 1, cur_bp: 5 },
                trigger_mode: TriggerMode::Discard,
            },
            &token_src,
        );

        assert!(
            matches!(guarded, WpdaStepAction::Advance(WpdaState::Unwinding)),
            "a target-owned operator rejected at the projection floor must suppress source consumption, got {guarded:?}"
        );
    }

    #[test]
    fn projection_target_floor_keeps_source_operator_that_produces_target() {
        let token_kinds = [TokenKind::Fixed("+".into()), TokenKind::Eof];
        let token_texts = ["+", ""];
        let token_src = SliceTokenSource::with_texts(&token_kinds, &token_texts);
        let mut w = WpdaWalker::new(ProjectionBoundaryProbeEngine, 0);
        let mut cursor = w.branch_cursors_for_test()[0].clone();
        cursor.inner_state = WpdaState::InfixLoop { cur_bp: 3 };
        let _ = w.cursor_gss_push_with_kind(
            &mut cursor,
            StackSymbolV2::category_entry(2),
            0,
            lex(0.0, 2, 0),
            crate::gss::EdgeKind::CrossCatProjection {
                source_src_idx: 2,
                inner_cur_bp: 3,
                wrap_cat: 1,
                wrap_rule: 0,
            },
        );

        let guarded = w.guard_crosscat_projection_target_boundary(
            &cursor,
            WpdaStepAction::ConsumeAndPush {
                symbol: StackSymbolV2::rule_at(1, 0, 0, Some(3)).with_kind_return(),
                weight: lex(0.0, 1, 0),
                new_state: WpdaState::CrossCatDelegate { source_src_idx: 2, inner_cur_bp: 5 },
                trigger_mode: TriggerMode::Discard,
            },
            &token_src,
        );

        let WpdaStepAction::Fork { branches, consume_trigger } = guarded else {
            panic!("expected category-changing source fork, got {guarded:?}");
        };
        assert!(!consume_trigger);
        assert_eq!(branches.len(), 2);
        assert!(matches!(
            branches[0].action_kind,
            ForkActionKind::ConsumeAndPush { trigger_mode: TriggerMode::Discard }
        ));
        assert!(matches!(branches[0].new_state, WpdaState::CrossCatDelegate { .. }));
        assert!(matches!(branches[1].action_kind, ForkActionKind::Advance));
        assert!(matches!(branches[1].new_state, WpdaState::Unwinding));
    }

