    #[test]
    fn synthesized_chain_body_origin_resolves_crosscat_lhs_cohort() {
        let mut w = WpdaWalker::new(ScriptedEngine::new(vec![]), 0);
        let mut cursor = w.branch_cursors_for_test()[0].clone();
        cursor.pos = 5;
        cursor.inner_state = WpdaState::Unwinding;
        cursor.last_action_output_cat = Some(7);

        let key = crate::dispatch_cohort::DispatchKey::new_crosscat_lhs(0, 2, 0, 7, u16::MAX);
        assert!(matches!(
            w.dispatch_cohort_cache
                .register(key.clone(), lex(0.0, 0, 0)),
            crate::dispatch_cohort::RegisterOutcome::WorkerInserted
        ));

        let symbol_id = w.sppf.intern_symbol(7, 0, 5);
        let origin = CrossCatLhsBodyOrigin {
            source_src_idx: 2,
            origin: crate::gss::CrossCatLhsReentryOrigin {
                dispatch_pos: 0,
                key_min_bp: 0,
                wrap_cat: 7,
                wrap_rule: u16::MAX,
            },
        };

        w.publish_crosscat_lhs_body_origins_for_synth_symbol(&cursor, symbol_id, vec![origin]);

        match w.dispatch_cohort_cache.register(key, lex(0.0, 0, 0)) {
            crate::dispatch_cohort::RegisterOutcome::ResolvedHit { bodies, .. } => {
                assert_eq!(bodies.len(), 1);
                assert_eq!(bodies[0].symbol_id, symbol_id);
                assert_eq!(bodies[0].hi_pos, 5);
            },
            _ => panic!("expected synthesized body to resolve cohort"),
        }
    }

    /// CrossCatLhs source parsing starts at the source prefix floor, but its
    /// post-body infix continuation must resume at the caller's active Pratt
    /// floor. Otherwise a delegated RHS of a high-precedence operator can later
    /// consume a lower-precedence category-changing operator.
    ///
    /// CLUSTER-A FIX (2026-06-20): restored to its pre-655095cf form. 655095cf
    /// flipped this assertion (and the production code) to clamp the source
    /// body's OWN floor up to the caller floor (`cur_bp: 11`), which regressed
    /// `led_chain_num_to_pred` — the delegated source RHS `4 == 4` of `and`
    /// could no longer fire its low-bp cross-category `==`. The source body must
    /// begin at floor 0; only the RESUME floor (`source_resume_bp` /
    /// `target_resume_bp`) carries the caller's floor, re-applied AFTER the body
    /// completes. See `normalize_crosscat_lhs_push_state`.
    #[test]
    fn crosscat_lhs_source_resume_uses_caller_floor() {
        let engine = ScriptedEngine::new(vec![]);
        let w = WpdaWalker::new(engine, 0);
        let mut cursor = w.branch_cursors_for_test()[0].clone();
        cursor.inner_state = WpdaState::PrefixDispatch { pos: 0, cur_bp: 11 };

        let (new_state, source_resume_bp, target_resume_bp) =
            WpdaWalker::<LexicographicWeight, ScriptedEngine>::normalize_crosscat_lhs_push_state(
                &cursor,
                WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
            );

        // The source body's OWN parse floor is left at its natural value (0):
        // it is an independent sub-parse, not a continuation of the caller.
        assert!(matches!(new_state, WpdaState::PrefixDispatch { cur_bp: 0, .. }));
        // The resume floors still carry the caller's active floor (11) so the
        // post-body infix continuation resumes at the enclosing precedence.
        assert_eq!(source_resume_bp, 11);
        assert_eq!(target_resume_bp, 11);
    }

    /// Mechanism γ — `ConsumeAndReplace` fork branch advances pos by 1.
    /// Mirrors `WpdaStepAction::ConsumeAndReplace` semantics inside Fork.
    #[test]
    fn fork_action_consume_and_replace_advances_pos() {
        let engine = ScriptedEngine::new(vec![
            WpdaStepAction::Accept,
            WpdaStepAction::Fork {
                branches: vec![ForkBranch {
                    symbol: StackSymbolV2::rule_at(0, 0, 1, None),
                    weight: lex(0.0, 0, 0),
                    new_state: WpdaState::Unwinding,
                    action_kind: ForkActionKind::ConsumeAndReplace,
                }],
                consume_trigger: false,
            },
            WpdaStepAction::Push {
                symbol: StackSymbolV2::category_entry(0),
                weight: lex(0.0, 0, 0),
                new_state: WpdaState::PrefixDispatch { pos: 0, cur_bp: 0 },
            },
        ]);
        let mut w = WpdaWalker::new(engine, 0);
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens()); // Push
        let pos_before_fork = w.position();
        let _ = w.process_event(WpdaEvent::Step, &empty_tokens()); // Fork
        let cursors = w.branch_cursors_for_test();
        assert_eq!(cursors.len(), 1);
        assert_eq!(
            cursors[0].pos,
            pos_before_fork + 1,
            "ConsumeAndReplace fork branch must advance child cursor's pos by 1",
        );
    }

    /// Mechanism γ — `Consume` fork branch advances pos by 1 without GSS change.
